import {retainedResumeFile,retainResumeFile,clearResumeFile} from './resume-file-store.mjs?v=126';
import {restoreBackupToExtension} from './backup-extension-restore.mjs?v=130';
import {cleanApplication} from './local-applications.mjs?v=117';
import {autofillPayload} from './autofill-profile.mjs?v=132';
import {downloadLocal} from './browser-documents.mjs?v=117';
const KEYS=['nextrole-retained-resume-v1','nextrole-profile','nextrole-autofill-profile-v1','nextrole-local-applications-v1','nextrole-saved'];
export const encode64=bytes=>{let s='';for(let i=0;i<bytes.length;i+=32768)s+=String.fromCharCode(...bytes.slice(i,i+32768));return btoa(s);};
const decode64=s=>{if(typeof s!=='string'||s.length>18000000||!/^[A-Za-z0-9+/]*={0,2}$/.test(s))throw Error('Invalid backup encoding.');return Uint8Array.from(atob(s),c=>c.charCodeAt(0));};
async function key(password,salt){if(typeof password!=='string'||password.length<12)throw Error('Use a backup password of at least 12 characters.');const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:310000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);}
export async function encryptBackup(data,password){const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),k=await key(password,salt),bytes=new TextEncoder().encode(JSON.stringify(data));if(bytes.length>12000000)throw Error('Backup exceeds the supported size.');const encrypted=await crypto.subtle.encrypt({name:'AES-GCM',iv},k,bytes);return {format:'nextrole-encrypted-backup',version:1,salt:encode64(salt),iv:encode64(iv),ciphertext:encode64(new Uint8Array(encrypted))};}
export async function decryptBackup(data,password){if(data?.format!=='nextrole-encrypted-backup'||data.version!==1)throw Error('Choose a NextRole encrypted backup.');const salt=decode64(data.salt),iv=decode64(data.iv);if(salt.length!==16||iv.length!==12)throw Error('Invalid backup.');try{const k=await key(password,salt),plain=await crypto.subtle.decrypt({name:'AES-GCM',iv},k,decode64(data.ciphertext));return validateBackup(JSON.parse(new TextDecoder().decode(plain)));}catch{throw Error('The password is incorrect or the backup is damaged.');}}
export function validateBackup(data){if(data?.format!=='nextrole-portable'||data.version!==1||!data.entries||typeof data.entries!=='object'||Array.isArray(data.entries))throw Error('Invalid portable backup.');for(const [name,value] of Object.entries(data.entries)){if(!KEYS.includes(name)||typeof value!=='string'||value.length>1500000)throw Error('Unsupported backup data.');const v=JSON.parse(value);if(name==='nextrole-saved'&&(!Array.isArray(v)||v.length>5000||v.some(x=>typeof x!=='string'||x.length>500)))throw Error('Invalid saved jobs backup.');if(name==='nextrole-retained-resume-v1'&&(v?.version!==1||typeof v.text!=='string'||v.text.length>150000))throw Error('Invalid resume backup.');if(name==='nextrole-local-applications-v1'){if(!Array.isArray(v)||v.length>500)throw Error('Invalid application backup.');v.forEach(cleanApplication);}if(name==='nextrole-autofill-profile-v1'){if(typeof v?.revision!=='string'||v.revision.length>100)throw Error('Invalid profile backup.');autofillPayload(v.profile);}if(name==='nextrole-profile'&&(!v||typeof v!=='object'||Array.isArray(v)||!Array.isArray(v.cities)||v.cities.length>50||v.cities.some(c=>typeof c!=='string')||!['any','Remote','Hybrid','On-site'].includes(v.workstyle)||!Number.isFinite(Number(v.experience))||Number(v.experience)<0||Number(v.experience)>80))throw Error('Invalid preferences backup.');}if(data.file){if(typeof data.file.name!=='string'||!/^.+\.(pdf|docx)$/i.test(data.file.name)||decode64(data.file.bytes).length>5*1024*1024)throw Error('Invalid resume attachment.');}return data;}
export function restoreEntries(data,storage){const old=new Map(KEYS.map(k=>[k,storage.getItem(k)]));const reset=()=>{for(const k of KEYS)storage.removeItem(k);for(const [k,v] of old)if(v!==null)storage.setItem(k,v);};try{for(const k of KEYS)storage.removeItem(k);for(const k of KEYS)if(data.entries[k]!==undefined)storage.setItem(k,data.entries[k]);}catch{try{reset();}catch{}throw Error('Browser storage is unavailable or full. Restore did not complete.');}return reset;}

export function setupPortableBackup(){const button=document.createElement('button');button.type='button';button.className='sidebar-tool';button.innerHTML='<span class="tool-icon" aria-hidden="true">⇄</span><span><strong>Backup &amp; move devices</strong><small>Save or restore your progress</small></span>';button.id='backup-setup';document.getElementById('application-tools').append(button);const dialog=document.createElement('dialog');dialog.className='public-guide';dialog.innerHTML='<button type="button" class="inbox-close" aria-label="Close backup">×</button><h2>Keep your progress across devices</h2><p>Download an encrypted backup of your website resume, retained resume file, reviewed profile, preferences, saved job IDs and application tracker. Save it privately in your own cloud drive, then restore it in NextRole on another device. There is no automatic sync or cloud upload.</p><label>Backup password (at least 12 characters)<input data-password type="password" autocomplete="new-password" minlength="12"></label><button type="button" class="find-jobs" data-export>Download encrypted backup</button><h3>Restore on this device</h3><label>Choose encrypted backup<input data-file type="file" accept=".json,application/json"></label><label class="autofill-confirm"><input data-approve type="checkbox"> Replace this website’s resume, profile, preferences, saved jobs and application records with this backup.</label><label class="autofill-confirm"><input data-extension type="checkbox" checked> Also restore my profile and resume to the extension</label><button type="button" class="secondary" data-import>Restore backup</button><button type="button" class="secondary" data-extension-retry hidden>Retry extension restore</button><p role="status" data-status></p><button type="button" class="secondary" data-reload hidden>Reload NextRole</button>';
 document.body.append(dialog);const q=s=>dialog.querySelector(s);let restoredData=null,controller=null,busy=false;
 function discard(){controller?.abort();restoredData=null;q('[data-password]').value='';}
 q('[data-reload]').onclick=()=>location.reload();button.onclick=()=>{discard();q('[data-approve]').checked=false;q('[data-extension]').checked=true;q('[data-extension-retry]').hidden=true;q('[data-reload]').hidden=true;q('[data-status]').textContent='';dialog.showModal();};q('.inbox-close').onclick=()=>{discard();dialog.close();};dialog.addEventListener('cancel',discard);
 function setBusy(value){busy=value;button.disabled=value;for(const control of dialog.querySelectorAll('input,button'))if(!control.classList.contains('inbox-close'))control.disabled=value;}
 async function restoreExtension(){
  q('[data-extension-retry]').hidden=true;q('[data-status]').textContent='Website restored. Connecting to the extension…';
  try{const result=await restoreBackupToExtension(restoredData,{signal:controller.signal,onConfirm:()=>{q('[data-status]').textContent='Website restored. Confirm Save profile and resume in the extension window.';}});if(controller.signal.aborted)return;
   if(result.state==='saved'){try{localStorage.setItem('nextrole-autofill-save-receipt-v1',JSON.stringify({fingerprint:result.fingerprint,savedAt:Date.now()}));}catch{}q('[data-status]').textContent='Website and extension restored. Reload NextRole to use your restored details.';}
   else{q('[data-status]').textContent='Website restored. Extension restore cancelled; its previous documents were kept.';q('[data-extension-retry]').hidden=false;}
  }catch(error){if(controller.signal.aborted)return;q('[data-status]').textContent='Website restored. Extension was not restored: '+error.message;q('[data-extension-retry]').hidden=false;}
 }
 q('[data-extension-retry]').onclick=async()=>{if(busy||!restoredData)return;setBusy(true);controller=new AbortController();try{await restoreExtension();}finally{setBusy(false);}};
 q('[data-export]').onclick=async()=>{const b=q('[data-export]');b.disabled=true;try{const entries=Object.fromEntries(KEYS.map(k=>[k,localStorage.getItem(k)]).filter(([,v])=>v!==null)),text=document.getElementById('resume-text').value,file=await retainedResumeFile(text),data={format:'nextrole-portable',version:1,entries};if(file)data.file={name:file.name,type:file.type,bytes:encode64(new Uint8Array(await file.arrayBuffer()))};const encrypted=await encryptBackup(data,q('[data-password]').value);downloadLocal(JSON.stringify(encrypted),'nextrole-encrypted-backup.json','application/json');q('[data-status]').textContent='Encrypted backup downloaded. Save it privately and keep your password separately.';}catch(e){q('[data-status]').textContent=e.message;}finally{b.disabled=false;}};
 q('[data-import]').onclick=async()=>{if(busy)return;setBusy(true);let rollback,previousFile,previousText='';restoredData=null;q('[data-extension-retry]').hidden=true;controller=new AbortController();const restoreExtensionToo=q('[data-extension]').checked;
  try{if(!q('[data-approve]').checked)throw Error('Confirm replacing this website’s data first.');const file=q('[data-file]').files[0];if(!file||file.size>18000000)throw Error('Choose a NextRole encrypted backup smaller than 18 MB.');
   const data=await decryptBackup(JSON.parse(await file.text()),q('[data-password]').value);if(controller.signal.aborted)return;
   previousText=JSON.parse(localStorage.getItem('nextrole-retained-resume-v1')||'{"text":""}').text||'';previousFile=await retainedResumeFile(previousText);
   rollback=restoreEntries(data,localStorage);const text=JSON.parse(data.entries['nextrole-retained-resume-v1']||'{"text":""}').text||'';
   const saved=data.file?await retainResumeFile(new File([decode64(data.file.bytes)],data.file.name,{type:data.file.type||''}),text):await clearResumeFile();
   if(!saved)throw Error('The resume file could not be restored.');
   rollback=null;restoredData=data;try{localStorage.removeItem('nextrole-autofill-save-receipt-v1');}catch{}q('[data-extension-retry]').hidden=true;q('[data-reload]').hidden=false;q('[data-password]').value='';
   if(restoreExtensionToo&&!controller.signal.aborted)await restoreExtension();else q('[data-status]').textContent='Website restored. Reload NextRole to use these details.';
  }catch(error){if(rollback){let recovered=true;try{rollback();if(previousFile)recovered=await retainResumeFile(previousFile,previousText);else recovered=await clearResumeFile();}catch{recovered=false;}q('[data-status]').textContent=error.message+(recovered?' Previous website data restored.':' Previous data could not be fully recovered; keep your backup and retry.');}else q('[data-status]').textContent=error.message;}
  finally{setBusy(false);}
 };
}
